// Inspired by the goose programming language variable size enum 05_shapes.goose

use std::marker::PhantomData;

pub use bytemuck;
pub use variable_size_enum_macro::variable_enum;

// Marker Trait implemented by every structure generated by variable_enum
pub trait VariableEnum: Sized {
    type Kind: Copy;
    const MAX_SIZE: usize;

    fn kind(&self) -> Self::Kind;
    fn write_to_uninit(&self, out: &mut [::core::mem::MaybeUninit<u8>]) -> usize;
    fn from_bytes(bytes: &[u8]) -> (Self, usize);
}

pub struct VariableVec<T> {
    variable_enum: std::marker::PhantomData<T>,
    storage: Vec<u8>,
}

impl<T> VariableVec<T>
where
    T: VariableEnum,
{
    pub fn new() -> Self {
        Self {
            variable_enum: PhantomData,
            storage: Vec::new(),
        }
    }

    pub fn push(&mut self, item: T) {
        let start = self.storage.len();
        // Bump allocate size
        self.storage.reserve(T::MAX_SIZE);

        let spare = self.storage.spare_capacity_mut();
        let written = item.write_to_uninit(&mut spare[..T::MAX_SIZE]);

        // SAFETY: write_to_uninit guarantees 'written' bytes have been initialized
        unsafe {
            self.storage.set_len(start + written);
        }
    }
}

impl<T> Default for VariableVec<T>
where
    T: VariableEnum,
{
    fn default() -> Self {
        Self::new()
    }
}

impl<T> Iterator for VariableVec<T> {
    type Item = T;

    fn next(&mut self) -> Option<Self::Item> {
        if false {
            // Some(from_bytes()); offset += from_bytes().len
            None
        } else {
            None
        }
    }
}

pub fn test() -> u8 {
    1
}
